using namespace biglybtc::services::azureus_control;
namespace {
std::size_t cases=0,assertions=0;
void check(bool value,const char* why){++assertions;if(!value){throw std::runtime_error(why);}}
template<class T>void ok(const std::expected<T,LookupError>& value){check(value.has_value(),"controller rejected admitted literal event");}
LookupOptions options(){LookupOptions value;value.localId[0]=255;return value;}
AdmittedContact contact(std::uint8_t id,bool owned=true){AdmittedContact value;value.owned=owned;value.contact.id.back()=id;value.contact.protocol=55;value.contact.address.bytes[0]=127;value.contact.address.bytes[3]=static_cast<std::uint8_t>(id+1);value.contact.address.port=static_cast<std::uint16_t>(40000+id);return value;}
Value value(std::uint8_t origin,std::string bytes){Value result;result.originator=contact(origin).contact;result.bytes=std::move(bytes);result.version=17;result.created=-1;return result;}
void begin(LookupController& c,std::initializer_list<AdmittedContact> seeds,LookupOptions o=options(),std::int64_t now=0){ok(c.start(1,7,o,{seeds.begin(),seeds.size()},now));}
LookupSnapshot take(const LookupController& c){const auto s=c.snapshot();ok(s);check(validLookupSnapshot(*s),"own controller snapshot violates bounded facts");return *s;}
std::vector<QueryIntent> intents(LookupController& c,std::int64_t now){auto result=c.takeIntents(now);ok(result);return std::move(*result);}
}
int main(){try{const auto run=[](const char* name,auto body){body();++cases;std::cout<<"case "<<name<<'\n';};
 run("empty-and-invalid-start-never-produce-a-query",[]{LookupController c;auto s=c.snapshot();ok(s);check(s->state==LookupState::Idle&&s->nodes.empty()&&!validLookupSnapshot(*s),"default state fabricated an active lookup");check(!c.takeIntents(0),"unstarted controller emitted intents");auto o=options();check(!c.start(0,7,o,{},0)&&!c.start(1,0,o,{},0)&&!c.start(1,7,o,{},-1),"invalid identity/time accepted");o.parallelism=9;check(!c.start(1,7,o,{},0),"unbounded parallelism accepted");o=options();o.flags=1;check(!c.start(1,7,o,{},0),"unsupported flags silently mapped");o=options();check(!c.start(1,7,o,{},std::numeric_limits<std::int64_t>::max()),"deadline overflow accepted");begin(c,{});s=c.snapshot();ok(s);check(s->state==LookupState::Complete&&s->stop==LookupStop::Exhausted&&s->nodes.empty(),"explicit empty seed request did not finish honestly");});
 run("literal-xor-order-and-parallel-reservations",[]{LookupController c;auto o=options();o.target.back()=0x80;o.parallelism=2;begin(c,{contact(0x7f),contact(0x81),contact(0x10)},o);auto batch=intents(c,1);check(batch.size()==2&&batch[0].node==2&&batch[1].node==3,"XOR byte distance order changed");check(batch[0].target==o.target&&batch[0].maximumValues==32&&batch[0].flags==0,"intent lost exact target/quota");auto s=take(c);check(s.active==2&&s.nodes[1].state==LookupNodeState::Reserved&&!s.nodes[1].ticket,"intent falsely claimed send");ok(c.sent(2,101,1));ok(c.sent(3,102,1));check(intents(c,1).empty(),"parallelism exceeded actual/reserved slots");ok(c.finish(2,LookupNodeState::Timeout,2));batch=intents(c,2);check(batch.size()==1&&batch[0].node==1,"failure did not release next closest candidate");});
 run("actual-contact-reply-creates-only-observed-admitted-child-query",[]{LookupController c;auto o=options();o.parallelism=1;begin(c,{contact(100)},o);const auto root=intents(c,1)[0];ok(c.sent(root.node,11,1));auto sameEndpoint=contact(41);sameEndpoint.contact.address=contact(40).contact.address;AdmittedContact self=contact(20);self.contact.id=o.localId;const std::array next{contact(40),contact(20,false),contact(100),sameEndpoint,self};ok(c.contacts(1,next,false,2));auto s=take(c);check(s.nodes.size()==3&&s.nodes[1].parent==1&&s.nodes[1].depth==1&&s.nodes[2].state==LookupNodeState::Rejected,"observed ancestry/policy rejection changed");check(s.duplicateContacts==3&&s.rejectedContacts==1,"repeat/self/endpoint accounting changed");const auto child=intents(c,3);check(child.size()==1&&child[0].node==2,"unowned child was queried");ok(c.sent(2,12,3));const std::array found{value(40,std::string("a\0b",3))};ok(c.values(2,found,true,1,4));check(take(c).nodes[1].state==LookupNodeState::Partial&&take(c).active==1,"continuation released live request");ok(c.values(2,{},false,1,5));s=take(c);check(s.state==LookupState::Complete&&s.results.size()==1&&s.results[0].node==2&&s.results[0].value.bytes==std::string("a\0b",3),"recursive GET did not preserve owned result");});
 run("unowned-public-contact-is-recorded-but-cannot-authorize-a-query",[]{auto blocked=contact(10,false);blocked.contact.address.bytes[0]=192;LookupController c;begin(c,{blocked});const auto s=take(c);check(s.state==LookupState::Complete&&s.nodes[0].state==LookupNodeState::Rejected&&s.rejectedContacts==1&&intents(c,1).empty(),"discovery became ownership");LookupController bad;blocked.owned=true;const auto result=bad.start(1,7,options(),std::span{&blocked,1},0);check(!result&&result.error()==LookupError::Invalid,"owned public endpoint bypassed loopback boundary");});
 run("repeated-contacts-and-cycles-never-requery-an-ancestor",[]{LookupController c;auto o=options();o.parallelism=1;begin(c,{contact(100)},o);intents(c,1);ok(c.sent(1,1,1));const std::array child{contact(50)};ok(c.contacts(1,child,false,2));intents(c,2);ok(c.sent(2,2,2));const std::array cycle{contact(100),contact(50),contact(100)};ok(c.contacts(2,cycle,false,3));const auto s=take(c);check(s.nodes.size()==2&&s.duplicateContacts==3&&s.state==LookupState::Complete&&s.nodes[1].parent==1,"lookup expanded a cycle or lost observed parent");});
 run("source-value-dedup-is-originator-id-plus-exact-bytes",[]{LookupController c;begin(c,{contact(1)});intents(c,1);ok(c.sent(1,1,1));auto a=value(10,"a"),same=a;same.version=99;same.created=999;const std::array first{a,same,value(10,"b"),value(11,"a")};ok(c.values(1,first,true,1,2));auto s=take(c);check(s.results.size()==3&&s.duplicateValues==1&&s.nodes[0].values==3,"source originator+bytes identity changed");const std::array last{a};ok(c.values(1,last,false,1,3));s=take(c);check(s.results.size()==3&&s.duplicateValues==2&&s.results[0].value.version==17&&s.results[0].value.created==-1,"dedup replaced first actual metadata or ignored bytes");});
 run("two-final-value-replies-stop-normal-get-and-wait-real-cancel-ack",[]{LookupController c;begin(c,{contact(1),contact(2),contact(3)});intents(c,1);for(std::uint64_t i=1;i<=3;++i){ok(c.sent(i,100+i,1));}ok(c.values(1,{},false,1,2));check(take(c).state==LookupState::Running,"one empty value reply ended search");ok(c.values(2,{},false,1,2));auto s=take(c);check(s.state==LookupState::Stopping&&s.stop==LookupStop::TwoValueReplies&&s.nodes[2].state==LookupNodeState::Sent&&s.nodes[2].cancellationRequested,"pending query was falsely cancelled/completed");const auto cancellation=c.cancellationIntents();ok(cancellation);check(cancellation->size()==1&&(*cancellation)[0].ticket==103,"cancel intent lost actual ticket");ok(c.finish(3,LookupNodeState::Cancelled,3));s=take(c);check(s.state==LookupState::Complete&&s.valueReplies==2&&s.results.empty(),"normal source value-reply termination changed");const auto revision=s.revision;check(!c.values(3,{},false,1,4)&&take(c).revision==revision,"stale callback mutated terminal lookup");});
 run("source-stats-flag-does-not-use-two-reply-shortcut",[]{LookupController c;auto o=options();o.flags=8;begin(c,{contact(1),contact(2),contact(3)},o);intents(c,1);for(std::uint64_t i=1;i<=3;++i){ok(c.sent(i,i,1));}ok(c.values(1,{},false,1,2));ok(c.values(2,{},false,1,2));check(take(c).state==LookupState::Running&&take(c).valueReplies==2,"source FLAG_STATS used ordinary shortcut");ok(c.values(3,{},false,1,3));check(take(c).state==LookupState::Complete&&take(c).stop==LookupStop::Exhausted,"stats lookup failed to exhaust");});
 run("value-limit-keeps-live-partial-ticket-until-real-completion",[]{LookupController c;auto o=options();o.maximumValues=2;o.parallelism=2;begin(c,{contact(1),contact(2)},o);intents(c,1);ok(c.sent(1,10,1));ok(c.sent(2,20,1));const std::array found{value(10,"x"),value(11,"y")};ok(c.values(1,found,true,1,2));auto s=take(c);check(s.state==LookupState::Stopping&&s.stop==LookupStop::ValueLimit&&s.active==2&&s.nodes[0].state==LookupNodeState::Partial&&s.results.size()==2,"value cap fabricated final RPC completion");const auto cancels=c.cancellationIntents();ok(cancels);check(cancels->size()==2,"partial request was omitted from cancellation");ok(c.finish(1,LookupNodeState::Cancelled,3));ok(c.finish(2,LookupNodeState::Cancelled,3));check(take(c).state==LookupState::Complete,"value-limit ack did not settle");});
 run("closest-success-policy-skips-farther-unqueried-root",[]{LookupController c;auto o=options();o.parallelism=1;o.accuracy=1;begin(c,{contact(1),contact(100)},o);const auto batch=intents(c,1);check(batch.size()==1&&batch[0].node==1,"closest root priority changed");ok(c.sent(1,1,1));ok(c.contacts(1,{},false,2));check(intents(c,3).empty(),"farther contact queried after source closest criterion");const auto s=take(c);check(s.stop==LookupStop::Closest&&s.state==LookupState::Complete&&s.nodes[1].state==LookupNodeState::Skipped&&!s.nodes[1].ticket,"closest termination claimed an unsent branch");});
 run("failed-near-contact-does-not-count-as-successful-closest",[]{LookupController c;auto o=options();o.parallelism=1;o.accuracy=1;begin(c,{contact(1),contact(100)},o);intents(c,1);ok(c.sent(1,1,1));ok(c.finish(1,LookupNodeState::Timeout,2));const auto next=intents(c,3);check(next.size()==1&&next[0].node==2,"timeout incorrectly satisfied closest-success count");ok(c.sent(2,2,3));ok(c.contacts(2,{},false,4));check(take(c).state==LookupState::Complete,"fallback did not exhaust");});
 run("cancel-and-owner-close-retain-distinct-real-node-acks",[]{LookupController c;auto o=options();o.parallelism=2;begin(c,{contact(1),contact(2),contact(3)},o);intents(c,1);ok(c.sent(1,10,1));ok(c.sent(2,20,1));ok(c.cancel(2));auto s=take(c);check(s.nodes[2].state==LookupNodeState::Skipped&&s.nodes[0].state==LookupNodeState::Sent&&s.active==2,"cancel invented sent/cancelled state");ok(c.finish(1,LookupNodeState::Cancelled,3));ok(c.close(4));ok(c.finish(2,LookupNodeState::Closed,5));s=take(c);check(s.state==LookupState::Closed&&s.nodes[0].state==LookupNodeState::Cancelled&&s.nodes[1].state==LookupNodeState::Closed,"close rewrote actual per-query outcomes");LookupController cancelled;begin(cancelled,{contact(1)});intents(cancelled,1);ok(cancelled.sent(1,1,1));ok(cancelled.cancel(2));ok(cancelled.finish(1,LookupNodeState::Cancelled,3));check(take(cancelled).state==LookupState::Cancelled,"explicit cancellation became successful completion");});
 run("actual-submission-crossing-global-deadline-keeps-ticket-for-cancel",[]{LookupController c;auto o=options();o.timeoutMillis=10;begin(c,{contact(1)},o,100);intents(c,100);ok(c.sent(1,123,110));auto s=take(c);check(s.state==LookupState::Stopping&&s.stop==LookupStop::Deadline&&s.nodes[0].ticket==123&&s.nodes[0].state==LookupNodeState::Sent,"deadline forgot just-issued actual ticket");const auto cancels=c.cancellationIntents();ok(cancels);check(cancels->size()==1&&(*cancels)[0].ticket==123,"deadline cancel intent missing");ok(c.finish(1,LookupNodeState::Timeout,111));check(take(c).state==LookupState::TimedOut,"deadline did not retain distinct result");});
 run("backward-clock-stops-scheduling-without-time-wrap-or-fake-ack",[]{LookupController c;begin(c,{contact(1)},options(),10);intents(c,11);ok(c.sent(1,1,12));const auto error=c.takeIntents(10);check(!error&&error.error()==LookupError::Clock,"backward time accepted");auto s=take(c);check(s.updatedMillis==12&&s.state==LookupState::Stopping&&s.nodes[0].cancellationRequested,"clock error advanced/wrapped time or lost pending");ok(c.finish(1,LookupNodeState::Cancelled,13));s=take(c);check(s.state==LookupState::Failed&&s.stop==LookupStop::Clock,"clock failure was certified successful");});
 run("contact-cap-is-atomic-and-never-draws-unretained-children",[]{LookupController c;auto o=options();o.maximumContacts=3;o.parallelism=1;begin(c,{contact(1)},o);intents(c,1);ok(c.sent(1,1,1));const std::array tooMany{contact(2),contact(3),contact(4)};const auto result=c.contacts(1,tooMany,false,2);check(!result&&result.error()==LookupError::Limit,"contact cap ignored");const auto s=take(c);check(s.nodes.size()==1&&s.nodes[0].state==LookupNodeState::Replied&&s.state==LookupState::Failed&&s.stop==LookupStop::Capacity,"bounded reply partially invented branches or lost actual final reply");});
 run("sixty-fifth-final-slice-does-not-strand-already-completed-rpc",[]{LookupController c;auto o=options();o.flags=8;begin(c,{contact(1)},o);intents(c,1);ok(c.sent(1,1,1));for(std::int64_t i=2;i<66;++i){ok(c.values(1,{},true,1,i));}check(take(c).nodes[0].slices==64,"valid slice quota mismatch");const auto result=c.values(1,{},false,1,66);check(!result&&result.error()==LookupError::Limit,"slice quota ignored");const auto s=take(c);check(s.state==LookupState::Failed&&s.active==0&&s.nodes[0].state==LookupNodeState::Replied,"final overquota packet left nonexistent RPC pending");const auto cancels=c.cancellationIntents();ok(cancels);check(cancels->empty(),"cancel requested for already-final stream");});
 run("unsupported-contact-stream-and-diversification-never-invent-subqueries",[]{LookupController c;begin(c,{contact(1)});intents(c,1);ok(c.sent(1,1,1));const std::array found{contact(2)};const auto result=c.contacts(1,found,true,2);check(!result&&result.error()==LookupError::Unsupported,"contact streaming silently completed ticket");check(take(c).nodes.size()==1&&take(c).nodes[0].state==LookupNodeState::Partial,"unsupported contact stream fabricated a child/final reply");ok(c.finish(1,LookupNodeState::Cancelled,3));check(take(c).state==LookupState::Failed,"unsupported branch looked complete");LookupController diversified;begin(diversified,{contact(1)});intents(diversified,1);ok(diversified.sent(1,1,1));const std::array actual{value(10,"observed")};ok(diversified.values(1,actual,false,2,2));const auto s=take(diversified);check(s.results.size()==1&&s.nodes.size()==1&&s.state==LookupState::Failed&&s.stop==LookupStop::Unsupported,"diversification was hidden or fabricated active lookup");});
 run("snapshot-fences-reject-malformed-public-dto-fields",[]{LookupController c;begin(c,{contact(1)});intents(c,1);ok(c.sent(1,1,1));const auto good=take(c);auto bad=good;bad.nodes[0].parent=1;check(!validLookupSnapshot(bad),"cyclic node parent accepted");bad=good;bad.nodes[0].contact.address.bytes[0]=192;check(!validLookupSnapshot(bad),"owned public contact accepted");bad=good;bad.state=static_cast<LookupState>(99);check(!validLookupSnapshot(bad),"unknown state accepted");bad=good;bad.active=0;check(!validLookupSnapshot(bad),"wrong active count accepted");bad=good;bad.nodes[0].sentMillis.reset();check(!validLookupSnapshot(bad),"sent query without actual timestamp accepted");bad=good;bad.nodes[0].contact.address.bytes[15]=1;check(!validLookupSnapshot(bad),"noncanonical IPv4 endpoint alias accepted");});
 run("results-and-snapshots-own-full-binary-value-and-origin-metadata",[]{LookupController c;begin(c,{contact(1)});intents(c,1);ok(c.sent(1,1,1));std::array found{value(10,std::string(512,'x'))};found[0].bytes[11]='\0';found[0].created=std::numeric_limits<std::int64_t>::min();ok(c.values(1,found,true,1,2));auto first=take(c);found[0].bytes.assign("mutated");check(first.results[0].value.bytes.size()==512&&first.results[0].value.bytes[11]=='\0'&&first.results[0].value.created==std::numeric_limits<std::int64_t>::min(),"actual binary metadata not retained");first.results[0].value.bytes="caller";first.nodes[0].contact.id[0]=123;check(take(c).results[0].value.bytes.size()==512&&take(c).nodes[0].contact.id[0]==0,"snapshot aliases mutable controller state");std::array invalid{value(20,std::string(513,'x'))};const auto result=c.values(1,invalid,false,1,3);check(!result&&take(c).results.size()==1&&take(c).state==LookupState::Failed,"oversized value replaced actual earlier results");});
 run("dispatch-failure-never-claims-an-actual-ticket-or-timeout",[]{LookupController c;begin(c,{contact(1)});intents(c,1);check(!c.finish(1,LookupNodeState::Timeout,2),"unsent intent falsely timed out");ok(c.finish(1,LookupNodeState::Failed,2));const auto s=take(c);check(s.nodes[0].state==LookupNodeState::Failed&&!s.nodes[0].ticket&&!s.nodes[0].sentMillis&&s.state==LookupState::Complete,"dispatch rejection fabricated network facts");const auto revision=s.revision;check(!c.sent(1,1,3)&&take(c).revision==revision,"late submit retargeted settled lookup");});
 std::cout<<"PASS "<<cases<<" owned-ddb-control cases; "<<assertions<<" assertions; explicit GET observations only; no Java/runtime equality credit\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
